<!-- ===== PROCESS ===== -->
<section style="background: var(--gs-deep-bg, #0D1826); color: var(--gs-deep-fg, #FFFFFF); padding: 94px 0; position: relative; overflow: hidden;">
  <div style="position: absolute; inset: 0; background-image: linear-gradient(var(--gs-deep-grid, rgba(255,255,255,.025)) 1px, transparent 1px), linear-gradient(90deg, var(--gs-deep-grid, rgba(255,255,255,.025)) 1px, transparent 1px); background-size: 54px 54px; mask-image: radial-gradient(ellipse 70% 60% at 50% 30%, #000 40%, transparent 100%);"></div>
  <div style="max-width: 1240px; margin: 0 auto; padding: 0 24px; position: relative;">
    <div style="text-align: center; max-width: 620px; margin: 0 auto 58px;">
      <div style="display: inline-flex; align-items: center; gap: 11px; margin-bottom: 14px;"><span style="width: 30px; height: 2px; background: var(--gs-accent, #2CA69C);"></span><span style="color: var(--gs-accent-lite, #6FDED3); font-family: 'Space Grotesk'; font-weight: 600; letter-spacing: .16em; font-size: 13px;"><x-t k="procTag"/></span><span style="width: 30px; height: 2px; background: var(--gs-accent, #2CA69C);"></span></div>
      <h2 style="font-family: 'Space Grotesk'; font-weight: 700; font-size: clamp(30px, 3.6vw, 45px); line-height: 1.14; letter-spacing: -.02em;"><x-t k="procTitle"/></h2>
    </div>
    <div style="display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px;" class="gs-4col">
      <div style="text-align: center; padding: 0 8px;">
        <div style="width: 84px; height: 84px; border-radius: var(--gs-r-card, 20px); background: color-mix(in srgb, var(--gs-accent, #2CA69C) 12%, transparent); border: 1px solid color-mix(in srgb, var(--gs-accent, #2CA69C) 28%, transparent); color: var(--gs-accent-lite, #6FDED3); display: grid; place-items: center; margin: 0 auto 20px; position: relative;"><svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="6"/><path d="M20 20l-3.5-3.5"/></svg><span style="position: absolute; top: -10px; right: -10px; background: var(--gs-accent, #2CA69C); color: #fff; font-family: 'Space Grotesk'; font-weight: 700; font-size: 13px; width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center;">01</span></div>
        <h4 style="font-family: 'Space Grotesk'; font-weight: 600; font-size: 19px; margin-bottom: 10px;"><x-t k="p1T"/></h4>
        <p style="font-size: 14px; color: var(--gs-deep-muted, #A3B0BD); line-height: 1.65;"><x-t k="p1D"/></p>
      </div>
      <div style="text-align: center; padding: 0 8px;">
        <div style="width: 84px; height: 84px; border-radius: var(--gs-r-card, 20px); background: color-mix(in srgb, var(--gs-accent, #2CA69C) 12%, transparent); border: 1px solid color-mix(in srgb, var(--gs-accent, #2CA69C) 28%, transparent); color: var(--gs-accent-lite, #6FDED3); display: grid; place-items: center; margin: 0 auto 20px; position: relative;"><svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><polygon points="15.5 8.5 10.5 10.5 8.5 15.5 13.5 13.5 15.5 8.5"/></svg><span style="position: absolute; top: -10px; right: -10px; background: var(--gs-accent, #2CA69C); color: #fff; font-family: 'Space Grotesk'; font-weight: 700; font-size: 13px; width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center;">02</span></div>
        <h4 style="font-family: 'Space Grotesk'; font-weight: 600; font-size: 19px; margin-bottom: 10px;"><x-t k="p2T"/></h4>
        <p style="font-size: 14px; color: var(--gs-deep-muted, #A3B0BD); line-height: 1.65;"><x-t k="p2D"/></p>
      </div>
      <div style="text-align: center; padding: 0 8px;">
        <div style="width: 84px; height: 84px; border-radius: var(--gs-r-card, 20px); background: color-mix(in srgb, var(--gs-accent, #2CA69C) 12%, transparent); border: 1px solid color-mix(in srgb, var(--gs-accent, #2CA69C) 28%, transparent); color: var(--gs-accent-lite, #6FDED3); display: grid; place-items: center; margin: 0 auto 20px; position: relative;"><svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3l8 4.5v9L12 21l-8-4.5v-9L12 3z"/><path d="M12 12l8-4.5M12 12v9M12 12L4 7.5"/></svg><span style="position: absolute; top: -10px; right: -10px; background: var(--gs-accent, #2CA69C); color: #fff; font-family: 'Space Grotesk'; font-weight: 700; font-size: 13px; width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center;">03</span></div>
        <h4 style="font-family: 'Space Grotesk'; font-weight: 600; font-size: 19px; margin-bottom: 10px;"><x-t k="p3T"/></h4>
        <p style="font-size: 14px; color: var(--gs-deep-muted, #A3B0BD); line-height: 1.65;"><x-t k="p3D"/></p>
      </div>
      <div style="text-align: center; padding: 0 8px;">
        <div style="width: 84px; height: 84px; border-radius: var(--gs-r-card, 20px); background: color-mix(in srgb, var(--gs-accent, #2CA69C) 12%, transparent); border: 1px solid color-mix(in srgb, var(--gs-accent, #2CA69C) 28%, transparent); color: var(--gs-accent-lite, #6FDED3); display: grid; place-items: center; margin: 0 auto 20px; position: relative;"><svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M4 13v-1a8 8 0 0116 0v1"/><rect x="3" y="13" width="4" height="6" rx="1.5"/><rect x="17" y="13" width="4" height="6" rx="1.5"/><path d="M19 19a4 4 0 01-4 3h-1"/></svg><span style="position: absolute; top: -10px; right: -10px; background: var(--gs-accent, #2CA69C); color: #fff; font-family: 'Space Grotesk'; font-weight: 700; font-size: 13px; width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center;">04</span></div>
        <h4 style="font-family: 'Space Grotesk'; font-weight: 600; font-size: 19px; margin-bottom: 10px;"><x-t k="p4T"/></h4>
        <p style="font-size: 14px; color: var(--gs-deep-muted, #A3B0BD); line-height: 1.65;"><x-t k="p4D"/></p>
      </div>
    </div>
  </div>
</section>
